<script setup lang="ts">
import {onMounted,onUnmounted,ref,watch}from'vue';
import {remoteRealpath,remoteList,remoteStat,remoteRead,remoteReadFile,remotePrepare,remoteConfirm,remoteCommit,remoteCancel}from'@/lib/backend/api';
import type {RemoteFileEntry,RemoteFileMutation}from'@/lib/backend/types';
const props=defineProps<{sessionId:string;disabled:boolean}>();
const cwd=ref('/');const address=ref('/');const entries=ref<RemoteFileEntry[]>([]);const selected=ref<RemoteFileEntry|null>(null);const busy=ref(false);const error=ref('');const note=ref('');const progress=ref('');
const menu=ref<{x:number;y:number}|null>(null);const input=ref<HTMLInputElement|null>(null);
const operation=ref<'mkdir'|'create'|'rename'|'remove'|'chmod'|'edit'|null>(null);const name=ref('');const mode=ref('644');const text=ref('');const target=ref('');
let editDigest='';
const confirmation=ref<{id:string;generation:number;token:string;summary:string}|null>(null);
let generation=0;let disposed=false;const MAX_FILE=16*1024*1024;const MAX_TEXT=1024*1024;
const message=(e:unknown)=>typeof e==='string'?e:e instanceof Error?e.message:'文件操作失败';
function validName(value:string){return value!=='.'&&value!=='..'&&value.length>0&&value.length<=255&&!/[\\/\x00-\x1f\x7f]/.test(value);}
function join(value:string){if(!validName(value))throw Error('文件名无效');return `${cwd.value.replace(/\/$/,'')}/${value}`;}
function current(id:string,g:number){return !disposed&&id===props.sessionId&&g===generation&&!props.disabled;}
function cancelConfirmation(){const c=confirmation.value;confirmation.value=null;if(c)void remoteCancel(c.id,c.token).catch(()=>{});}
async function navigate(path=address.value){if(busy.value||props.disabled)return;const id=props.sessionId;const g=generation;busy.value=true;error.value='';menu.value=null;try{const resolved=await remoteRealpath(id,path);if(!current(id,g))return;const list=await remoteList(id,resolved);if(!current(id,g))return;entries.value=list.filter(e=>validName(e.name)).sort((a,b)=>(a.kind==='directory'?0:1)-(b.kind==='directory'?0:1)||a.name.localeCompare(b.name));cwd.value=resolved;address.value=resolved;selected.value=null;}catch(e){if(current(id,g))error.value=message(e);}finally{if(id===props.sessionId&&g===generation)busy.value=false;}}
function up(){const parent=cwd.value.replace(/\/$/,'').split('/').slice(0,-1).join('/')||'/';void navigate(parent);}
function context(event:MouseEvent,item:RemoteFileEntry|null){if(props.disabled||busy.value)return;selected.value=item;menu.value={x:Math.max(0,Math.min(event.clientX,window.innerWidth-180)),y:Math.max(0,Math.min(event.clientY,window.innerHeight-380))};}
function request(kind:NonNullable<typeof operation.value>){menu.value=null;error.value='';if(props.disabled||busy.value)return;if(!['mkdir','create'].includes(kind)&&!selected.value)return;operation.value=kind;name.value=kind==='rename'?selected.value!.name:'';target.value=selected.value?join(selected.value.name):cwd.value;mode.value=((selected.value?.permissions??0o644)&0o777).toString(8);}
async function mutate(mutation:RemoteFileMutation,summary:string){if(props.disabled||busy.value)return;const id=props.sessionId;const g=generation;busy.value=true;error.value='';try{const permit=await remotePrepare(id,mutation);if(!current(id,g)){void remoteCancel(id,permit.token).catch(()=>{});return;}operation.value=null;if(permit.confirmationRequired){confirmation.value={id,generation:g,token:permit.token,summary};return;}await remoteCommit(id,permit.token);if(current(id,g)){note.value='文件操作已完成';busy.value=false;await navigate(cwd.value);}}catch(e){if(current(id,g))error.value=message(e);}finally{if(id===props.sessionId&&g===generation)busy.value=false;}}
async function commit(){const c=confirmation.value;if(!c||busy.value||!current(c.id,c.generation))return;busy.value=true;confirmation.value=null;error.value='';try{await remoteConfirm(c.id,c.token);if(!current(c.id,c.generation)){void remoteCancel(c.id,c.token).catch(()=>{});return;}await remoteCommit(c.id,c.token);if(current(c.id,c.generation)){note.value='文件操作已完成';busy.value=false;await navigate(cwd.value);}}catch(e){void remoteCancel(c.id,c.token).catch(()=>{});if(current(c.id,c.generation))error.value=message(e);}finally{if(c.id===props.sessionId&&c.generation===generation)busy.value=false;}}
async function submitAction(){try{const kind=operation.value;if(!kind)return;let mutation:RemoteFileMutation;if(kind==='mkdir'||kind==='create')mutation={action:kind,path:join(name.value)};else if(kind==='rename')mutation={action:kind,path:target.value,destination:join(name.value)};else if(kind==='remove')mutation={action:kind,path:target.value,directory:selected.value?.kind==='directory'};else if(kind==='chmod'){if(!/^[0-7]{3}$/.test(mode.value))throw Error('请输入 000 至 777 权限');mutation={action:kind,path:target.value,mode:parseInt(mode.value,8)};}else{const bytes=new TextEncoder().encode(text.value);if(bytes.length>MAX_TEXT)throw Error('文本编辑上限为 1 MiB');mutation={action:'write',path:target.value,data:Array.from(bytes),overwrite:true,expectedDigest:editDigest};}await mutate(mutation,`${kind} ${target.value}${kind==='rename'?` → ${join(name.value)}`:''}`);}catch(e){error.value=message(e);}}
async function readWhole(path:string,limit:number){const id=props.sessionId;const g=generation;const result=await remoteReadFile(id,path,limit);if(!current(id,g))throw Error('会话已变化');if(result.bytes.length>limit||!result.bytes.every(n=>Number.isInteger(n)&&n>=0&&n<=255))throw Error('读取结果超出限制');return Uint8Array.from(result.bytes);}

async function open(item:RemoteFileEntry){selected.value=item;if(item.kind==='directory'){void navigate(join(item.name));return;}menu.value=null;if(busy.value||props.disabled)return;const id=props.sessionId,g=generation;busy.value=true;error.value='';try{const path=join(item.name);const bytes=await readWhole(path,MAX_TEXT);const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(b=>b.toString(16).padStart(2,'0')).join('');const decoded=new TextDecoder('utf-8',{fatal:true}).decode(bytes);if(decoded.includes('\0'))throw Error('二进制文件请下载后打开');if(current(id,g)){text.value=decoded;editDigest=digest;target.value=path;operation.value='edit';}}catch(e){if(current(id,g))error.value=message(e);}finally{if(id===props.sessionId&&g===generation){busy.value=false;progress.value='';}}}
async function download(){const item=selected.value;menu.value=null;if(!item||busy.value||props.disabled)return;const id=props.sessionId,g=generation;busy.value=true;error.value='';try{const bytes=await readWhole(join(item.name),MAX_FILE);if(!current(id,g))return;const url=URL.createObjectURL(new Blob([bytes],{type:'application/octet-stream'}));const a=document.createElement('a');a.href=url;a.download=item.name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);note.value='下载已交给系统保存';}catch(e){if(current(id,g))error.value=message(e);}finally{if(id===props.sessionId&&g===generation){busy.value=false;progress.value='';}}}
async function upload(event:Event){const picker=event.target as HTMLInputElement;const file=picker.files?.[0];picker.value='';if(!file||props.disabled||busy.value)return;const id=props.sessionId,g=generation,path=cwd.value;if(file.size>MAX_FILE){error.value='单文件传输上限为 16 MiB';return;}busy.value=true;error.value='';try{if(!validName(file.name))throw Error('文件名无效');const bytes=new Uint8Array(await file.arrayBuffer());if(!current(id,g)||path!==cwd.value)return;busy.value=false;await mutate({action:'write',path:join(file.name),data:Array.from(bytes),overwrite:false},`上传 ${file.name}（${file.size} 字节，不覆盖已有文件）`);}catch(e){if(current(id,g))error.value=message(e);}finally{if(id===props.sessionId&&g===generation)busy.value=false;}}
async function copyPath(){menu.value=null;try{await navigator.clipboard.writeText(selected.value?join(selected.value.name):cwd.value);note.value='路径已复制';}catch{error.value='无法访问剪贴板';}}
function outside(event:MouseEvent){if(!(event.target as HTMLElement).closest('.remote-context-menu'))menu.value=null;}
function initialize(){generation++;cancelConfirmation();busy.value=false;entries.value=[];selected.value=null;operation.value=null;menu.value=null;text.value='';error.value='';note.value='';if(props.sessionId&&!props.disabled)void navigate('.');}
watch(()=>[props.sessionId,props.disabled],initialize);onMounted(()=>{initialize();document.addEventListener('click',outside);});onUnmounted(()=>{disposed=true;generation++;cancelConfirmation();document.removeEventListener('click',outside);});
</script>
<template>
 <section class="remote-files" aria-label="SFTP 文件管理"><div class="resource-toolbar"><button type="button" :disabled="busy||disabled" @click="up">上一级</button><input v-model="address" aria-label="远程路径" :disabled="busy||disabled" @keydown.enter="navigate()" /><button type="button" :disabled="busy||disabled" @click="navigate()">前往</button><button type="button" :disabled="busy||disabled" @click="navigate(cwd)">刷新</button><button type="button" :disabled="busy||disabled" @click="input?.click()">上传</button><input ref="input" class="file-picker" type="file" aria-label="上传本地文件" @change="upload" /><small>SFTP · 单文件 ≤16 MiB {{progress}}</small></div><p v-if="error" role="alert" class="inline-error">{{error}}</p><p v-if="note" role="status" class="resource-note">{{note}}</p>
 <div class="file-browser"><nav class="file-shortcuts" aria-label="目录快捷入口"><button type="button" :disabled="busy||disabled" @click="navigate('/')">▸ 根目录 /</button><button type="button" :disabled="busy||disabled" @click="navigate('.')">▸ 登录目录</button><button type="button" :disabled="busy||disabled" @click="request('mkdir')">＋ 新建文件夹</button><button type="button" :disabled="busy||disabled" @click="request('create')">＋ 新建文件</button></nav><div class="file-table-wrap" @contextmenu.prevent="context($event,null)"><table class="file-table"><thead><tr><th>文件名</th><th>大小</th><th>类型</th><th>修改时间</th><th>权限</th></tr></thead><tbody><tr v-for="item in entries" :key="item.name" data-test="file-row" :class="{'is-selected':selected?.name===item.name}" tabindex="0" @click="selected=item" @dblclick="open(item)" @keydown.enter.prevent="open(item)" @contextmenu.stop.prevent="context($event,item)"><td><span aria-hidden="true">{{item.kind==='directory'?'📁':item.kind==='symlink'?'↗':'▤'}}</span> {{item.name}}</td><td>{{item.size===null?'—':item.size.toLocaleString()}}</td><td>{{{directory:'文件夹',file:'文件',symlink:'符号链接',unknown:'未知'}[item.kind]}}</td><td>{{item.modified===null?'—':new Date(item.modified*1000).toLocaleString()}}</td><td>{{item.permissions===null?'—':(item.permissions&0o777).toString(8).padStart(3,'0')}}</td></tr></tbody></table><p v-if="!entries.length" class="empty-state">{{busy?'正在读取目录…':disabled?'会话不可用':'目录为空'}}</p></div></div>
 <div v-if="menu" class="remote-context-menu" role="menu" :style="{left:`${menu.x}px`,top:`${menu.y}px`}" @keydown.esc="menu=null"><button type="button" role="menuitem" @click="menu=null;navigate(cwd)">刷新</button><button type="button" role="menuitem" :disabled="!selected" @click="selected&&open(selected)">打开 / 文本编辑</button><button type="button" role="menuitem" @click="copyPath">复制路径</button><button type="button" role="menuitem" :disabled="selected?.kind!=='file'" @click="download">下载</button><button type="button" role="menuitem" @click="menu=null;input?.click()">上传…</button><hr /><button type="button" role="menuitem" @click="request('mkdir')">新建文件夹</button><button type="button" role="menuitem" @click="request('create')">新建文件</button><button type="button" role="menuitem" :disabled="!selected" @click="request('rename')">重命名</button><button data-test="delete-file" type="button" role="menuitem" :disabled="!selected" @click="request('remove')">删除</button><button type="button" role="menuitem" :disabled="!selected||selected.kind==='symlink'" @click="request('chmod')">文件权限…</button></div>
 <div v-if="operation" class="file-action-editor" role="region" aria-label="文件操作"><strong>{{{mkdir:'新建文件夹',create:'新建文件',rename:'重命名',remove:'确认删除',chmod:'修改权限',edit:'文本编辑'}[operation]}}</strong><p>{{target}}</p><input v-if="['mkdir','create','rename'].includes(operation)" v-model="name" aria-label="文件名称" :disabled="busy" @keydown.enter="submitAction" /><input v-if="operation==='chmod'" v-model="mode" aria-label="八进制权限" maxlength="3" :disabled="busy" /><textarea v-if="operation==='edit'" v-model="text" aria-label="远程文本内容" spellcheck="false" rows="8" :disabled="busy" /><p v-if="operation==='remove'">删除不可撤销。文件夹必须为空；不会执行递归 Shell 删除。</p><p v-if="operation==='edit'">保存前会检查文件内容是否变化；服务端并发修改仍可能发生。保存会覆盖文件，中断可能留下部分内容，请先保留备份。</p><div class="resource-actions"><button data-test="submit-file-action" type="button" :disabled="busy||disabled" @click="submitAction">{{operation==='edit'?'保存文件':operation==='remove'?'确认删除':'确定'}}</button><button type="button" :disabled="busy" @click="operation=null;text=''">取消</button></div></div>
 <div v-if="confirmation" class="warning-box" role="alert" aria-label="确认远端文件变更"><strong>确认远端文件变更</strong><p>{{confirmation.summary}}</p><p>此操作会修改当前服务器文件，可能不可撤销。</p><button data-test="cancel-file-confirm" type="button" :disabled="busy" @click="cancelConfirmation">取消</button><button type="button" :disabled="busy||disabled" @click="commit">确认执行</button></div>
 </section>
</template>
<style scoped>
.remote-files{font-size:12px}.file-picker{display:none}.file-browser{display:grid;grid-template-columns:155px minmax(0,1fr);min-height:230px}.file-shortcuts{padding:8px 0;border-right:1px solid var(--border)}.file-shortcuts button{display:block;text-align:left;width:100%;border:0;border-radius:0;background:var(--surface);padding:9px 12px}.file-table-wrap{overflow:auto;max-height:330px}.file-table{border-collapse:collapse;width:100%;white-space:nowrap}.file-table th,.file-table td{text-align:left;padding:7px 10px;border-bottom:1px solid var(--border)}.file-table th{position:sticky;top:0;background:var(--chrome);color:var(--muted);font-weight:500}.file-table tbody tr:hover,.file-table .is-selected{background:var(--selection)}.file-table td:first-child{max-width:320px;overflow:hidden;text-overflow:ellipsis}.remote-context-menu{position:fixed;z-index:150;display:grid;min-width:170px;padding:5px;background:var(--surface);border:1px solid var(--border);box-shadow:0 5px 18px #182c3833;border-radius:6px}.remote-context-menu button{border:0;background:var(--surface);text-align:left;padding:7px 13px}.remote-context-menu button:hover:not(:disabled){background:var(--selection)}.remote-context-menu hr{width:100%;border:0;border-top:1px solid var(--border);margin:4px 0}.file-action-editor{padding:14px;border-top:1px solid var(--border);display:grid;gap:9px;background:var(--chrome)}.file-action-editor p{margin:0;overflow-wrap:anywhere}.file-action-editor textarea{font:13px/1.5 Consolas,monospace;resize:vertical}.file-action-editor input,.file-action-editor textarea{border:1px solid var(--input-border);border-radius:4px;padding:8px}.resource-actions{display:flex;gap:8px}.resource-note{padding:0 12px;color:var(--accent)}@media(max-width:720px){.file-browser{grid-template-columns:1fr}.file-shortcuts{display:flex;flex-wrap:wrap;border-right:0}.file-shortcuts button{width:auto}}
</style>
